    for (house) |cell| {
        switch (cell) {
            .fixed => |num| fixed_nums.append(num) catch unreachable,
            .empty => {},
        }
    }

    var changed = false;
    for (house, 0..) |cell, i| {
        switch (cell) {
            .empty => {
                for (fixed_nums.constSlice()) |num| {
                    if (cell.empty.bits.get(num.toInt() - 1)) {
                        house[i].empty.remove(num);
                        changed = true;
                    }
                }
                if (house[i].empty.single()) |num| {
                    house[i] = Cell{ .fixed = num };
                    changed = true;
                }
            },
            .fixed => {},
        }
    }
    return changed;
}

