fn prune(self: *Self) void {
    var changing = true;
    while (changing) {
        changing = false;
        for (0..9) |i_usize| {
            const i: u4 = @intCast(i_usize);

            var house = self.getRow(i);
            if (pruneHouse(&house)) {
                changing = true;
                self.setRow(i, house);
            }

            house = self.getCol(i);
            if (pruneHouse(&house)) {
                changing = true;
                self.setCol(i, house);
            }

            house = self.getBox(i);
            if (pruneHouse(&house)) {
                changing = true;
                self.setBox(i, house);
            }
        }
    }
}

pub fn solve(self: *Self) SolveError!void {
    if (!self.isLegal()) {
        return error.IllegalPuzzle;
    } else if (!self.hasSufficientHints()) {
        return error.TooFewHints;
    }

    self.prune();

    const solved = try solveHelper(self, Coord.FIRST);

    self.* = solved;
}
