    for (house, 0..) |cell, i| {
        switch (cell) {
            .empty => {
                for (fixed_nums.constSlice()) |num| {
                    house[i].empty.remove(num);
                }
                if (house[i].empty.single()) |num| {
                    house[i] = Cell{ .fixed = num };
                }
            },
            .fixed => {},
        }
    }
